# apply_maskable_icons.ps1
# Adds maskable icons (butterfly at 70% on the same yellow) so launchers no longer crop the wings, points the two "maskable"
# manifest entries at them, then branch -> commit -> push -> PR -> merge in one run. ASCII only.
# Run from any folder; it works in $HOME\Downloads\hondi and deletes itself at the end.
$ErrorActionPreference = 'Stop'
Set-Location "$HOME\Downloads\hondi"
$branch = 'feat/maskable-icons'
git checkout main
git pull origin main --rebase
git checkout -b $branch
