[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) 'icons\navi-icon-maskable-512.png'), [Convert]::FromBase64String(($b512 -replace '\s','')))
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) 'icons\navi-icon-maskable-192.png'), [Convert]::FromBase64String(($b192 -replace '\s','')))
$mpath = Join-Path (Get-Location) 'manifest.json'
$txt = [System.IO.File]::ReadAllText($mpath, $utf8)
$pat = '"src": "/icons/navi-icon-(192|512)\.png(\?v=\d+)?",(\s*)"sizes": "\1x\1",(\s*)"type": "image/png",(\s*)"purpose": "maskable"'
$cnt = ([regex]::Matches($txt, $pat)).Count
if ($cnt -ne 2) { throw "expected 2 maskable entries, found $cnt - manifest changed upstream; aborting" }
$txt = [regex]::Replace($txt, $pat, '"src": "/icons/navi-icon-maskable-${1}.png?v=20261015",${3}"sizes": "${1}x${1}",${4}"type": "image/png",${5}"purpose": "maskable"')
[System.IO.File]::WriteAllText($mpath, $txt, $utf8)
$null = $txt | ConvertFrom-Json
